    /// <summary>Every native event name the schema declares.</summary>
    public static IReadOnlyCollection<string> EventNames => AllByName.Keys;

    /// <summary>Number of distinct native event names.</summary>
    public const int NameCount = 276;

    /// <summary>Number of event declarations, counting duplicates across source files.</summary>
    public const int DeclarationCount = 292;

    /// <summary>
    ///     Resolves the factory for the declaration CS2 fires for this name.
    /// </summary>
    public static bool TryGetFactory(string nativeName, out GameEventFactory factory) =>
        Preferred.TryGetValue(nativeName, out factory!);

    /// <summary>
    ///     Every declaration of <paramref name="nativeName"/>, highest-priority
    ///     source first. Empty when the name is unknown.
    /// </summary>
    public static IReadOnlyList<GameEventDeclaration> GetAllFactories(string nativeName) =>
        AllByName.TryGetValue(nativeName, out GameEventDeclaration[]? all) ? all : [];
}
